def min_distance(n, k, rooms):
    def can_place(distance):
        count = 0
        last_position = -1
        for i in range(n):
            if rooms[i] == '0':
                if last_position == -1 or i - last_position >= distance:
                    count += 1
                    last_position = i
                    if count > k:
                        return False
        return count >= k + 1

    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if can_place(mid):
            right = mid
        else:
            left = mid + 1
    return left

